"""Stored entities of the sandbox ledger (owned by Role C, generated by Role E).

The financial core never writes these; it reads one immutable LedgerSnapshot.
Text fields that come from third parties (merchant names) are DATA, never instructions.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from enum import Enum

from ..shared.month import Month


class AccountType(str, Enum):
    CHECKING = "checking"
    SAVINGS = "savings"
    CREDIT_CARD = "credit_card"


class TransactionKind(str, Enum):
    INCOME = "income"
    PURCHASE = "purchase"
    CARD_PAYMENT = "card_payment"
    TRANSFER_OWN = "transfer_own"  # card payments are classified here to avoid double counting cuotas
    REFUND = "refund"
    FEE = "fee"


class IncomeType(str, Enum):
    SALARIED = "salaried"
    FREELANCE = "freelance"


@dataclass(frozen=True, slots=True)
class Account:
    account_id: str
    type: AccountType
    balance: int
    currency: str


@dataclass(frozen=True, slots=True)
class InstallmentInfo:
    """Structured cuota metadata, like a card statement line 'CUOTA 03/12'."""

    plan_id: str
    installment_number: int
    installment_total: int
    original_amount: int
    monthly_rate: Decimal | None = None


@dataclass(frozen=True, slots=True)
class Transaction:
    txn_id: str
    account_id: str
    date: date
    amount: int  # signed, minor units
    merchant_raw: str  # untrusted third-party text
    category: str
    kind: TransactionKind
    installment: InstallmentInfo | None = None


@dataclass(frozen=True, slots=True)
class Goal:
    goal_id: str
    name: str
    target_amount: int
    deadline: Month
    saved_amount: int


@dataclass(frozen=True, slots=True)
class SavingsBucket:
    """Virtual allocation inside the sandbox savings account: 'reserve' or 'goal:<id>'."""

    bucket: str
    amount: int


@dataclass(frozen=True, slots=True)
class IncomeProfile:
    type: IncomeType
    contracted_net: int | None
    payday_rule: str  # e.g. "last_business_day"


@dataclass(frozen=True, slots=True)
class LedgerSnapshot:
    user_id: str
    currency: str
    as_of: date
    ledger_version: str
    accounts: tuple[Account, ...]
    transactions: tuple[Transaction, ...]
    goals: tuple[Goal, ...]
    buckets: tuple[SavingsBucket, ...]
    income_profile: IncomeProfile
